import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { setRequestAsOf } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import { useAsOf } from './sheet';

/** Whether the text is a real date as yyyy-mm-dd. */
function isDate(text: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const d = new Date(`${text}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === text;
}

/** The as-of date of this user's screen: shown ('' when none), set and cleared. Setting or clearing it re-reads
 *  everything under the sheet, as it stood at the end of that day or as it is now. */
function SheetAsOf({ sheetId }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [asOf, setAsOf] = useAsOf();
  const [typed, setTyped] = useState('');
  const [invalid, setInvalid] = useState(false);

  useEffect(() => {
    setRequestAsOf(asOf);
  }, [asOf]);

  const show = async (date: string) => {
    setRequestAsOf(date);
    setAsOf(date === '' ? undefined : date);
    await queryClient.resetQueries({ queryKey: ['sheet', sheetId] });
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const date = typed.trim();
    if (!isDate(date)) {
      setInvalid(true);
      return;
    }
    setInvalid(false);
    void show(date);
  };

  return (
    <section>
      <form data-testid="asof-form" onSubmit={submit}>
        <label>
          As of{' '}
          <input
            data-testid="asof-date"
            placeholder="yyyy-mm-dd"
            value={typed}
            onChange={(e) => {
              setTyped(e.target.value);
              setInvalid(false);
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="asof-set">
          Show as of
        </button>{' '}
        <button
          type="button"
          data-testid="asof-clear"
          onClick={() => {
            setInvalid(false);
            void show('');
          }}
        >
          Show now
        </button>
      </form>
      <p>
        Showing as of <strong data-testid="sheet-asof">{asOf}</strong>
      </p>
      {invalid && (
        <p data-testid="asof-error" role="alert">
          Enter the as-of date as a real date (yyyy-mm-dd).
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 0.5, Component: SheetAsOf });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

/** The date this screen shows the sheet as of ('' when it shows it as it is now): every read asks for the sheet as
 *  of it (?asOf=), and every change is sent marked with it (X-As-Of), so the server refuses it. Kept in step with
 *  the URL's asOf by features/sheet/asof; read from the URL at start-up so the first reads already carry it. */
let asOf = typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('asOf') ?? '';

export function setRequestAsOf(date: string): void {
  asOf = date;
}

function withAsOf(path: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}

function changeHeaders(): Record<string, string> {
  return asOf === '' ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/json', 'X-As-Of': asOf };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(withAsOf(path));
}

/** A read of the store as it is now, whatever date this screen shows the sheet as of. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}
