import { asString, useSearchParam } from '../../url/useSearchParam';

/** The signed-in name (no password) — kept in the URL like any other state that outlives a click. */
export function useUser() {
  return useSearchParam('user', asString);
}

/** The active sheet id. */
export function useSheetId() {
  return useSearchParam('sheet', asString);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { claimsQuery } from '../claims/claims';
import { notesQuery } from '../notes/notes';
import { peopleQuery } from '../people/people';
import { useSheetId } from '../session/session';

import type { Sheet } from './sheet';

/** Choose a sheet by id. Loading an id never used before starts an empty sheet; loading an id
 *  again re-reads everything under it from the store. */
export function SheetPicker({ user }: { user: string }) {
  const queryClient = useQueryClient();
  const [sheetId, setSheetId] = useSheetId();
  const [typed, setTyped] = useState('');
  const once = useSubmitOnce();

  const load = useMutation({
    mutationFn: (id: string) => putJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}`, { user }),
    onSuccess: async (sheet) => {
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheet.id] });
      // The sheet shows as loaded once its people, claims and notes are read, so its lists are never seen empty while they come.
      await Promise.all([
        queryClient.fetchQuery(peopleQuery(sheet.id)).catch(() => undefined),
        queryClient.fetchQuery(claimsQuery(sheet.id)).catch(() => undefined),
        queryClient.fetchQuery(notesQuery(sheet.id)).catch(() => undefined),
      ]);
      setSheetId(sheet.id);
    },
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    load.reset();
    const id = typed.trim();
    if (id === '') {
      setSheetId(undefined);
      return;
    }
    if (!once.start()) return;
    load.mutate(id);
  };

  return (
    <section>
      <form data-testid="sheet-form" onSubmit={submit}>
        <label>
          Sheet id{' '}
          <input
            data-testid="sheet-id-input"
            value={typed}
            onChange={(e) => {
              setTyped(e.target.value);
              load.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
          Load
        </button>
        {load.isError && (
          <p data-testid="sheet-load-error" role="alert">
            Could not load that sheet.
          </p>
        )}
      </form>
      {sheetId && (
        <p>
          Sheet <strong data-testid="sheet-current-id">{sheetId}</strong>
        </p>
      )}
    </section>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { LocaleFigures } from '../features/locale/LocaleFigures';
import { UserLocale } from '../features/locale/UserLocale';
import { useLocale } from '../features/locale/locale';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { useSheetId, useUser } from '../features/session/session';
import { SheetPicker } from '../features/sheet/SheetPicker';
import { SheetBody } from '../slots/defs/sheet';

// The one screen: sign in by name, choose a sheet by id, then everything kept per sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useUser();
  const [sheetId] = useSheetId();
  const locale = useLocale(user ?? '');

  if (!user) {
    return (
      <>
        <SignIn />
        <p data-testid="home-empty">Nothing here yet.</p>
      </>
    );
  }
  // Every figure shown to the signed-in user is in their locale.
  return (
    <LocaleFigures locale={locale}>
      <CurrentUser user={user} />
      <UserLocale user={user} />
      <SheetPicker user={user} />
      {sheetId ? (
        <SheetBody.Slot key={sheetId} sheetId={sheetId} user={user} />
      ) : (
        <p data-testid="home-empty">Nothing here yet.</p>
      )}
    </LocaleFigures>
  );
}
 *  or through others. */
function distinctPeople(names: string[][]): number {
  const parent = names.map((_, i) => i);
  const root = (i: number): number => (parent[i] === i ? i : (parent[i] = root(parent[i])));
  const owner = new Map<string, number>();
  names.forEach((ns, i) => ns.forEach((n) => {
    const key = nameKey(n);
    const other = owner.get(key);
    if (other === undefined) owner.set(key, i);
    else parent[root(i)] = root(other);
  }));
  return names.filter((_, i) => root(i) === i).length;
}

function Shown({ figures }: { figures: Figures }) {
  return (
    <p data-testid="consolidated">
      Consolidated: people <strong data-testid="consolidated-people-count">{distinctPeople(figures.names)}</strong>{' '}
      due total <strong data-testid="consolidated-due-total">{trimmedSum(figures.dues)}</strong>{' '}
      overdue total <strong data-testid="consolidated-overdue-total">{trimmedSum(figures.overdues)}</strong>
      {GRADES.map((g) => (
        <span key={g}>
          {' '}grade {g} due total <strong data-testid={`consolidated-grade-${g}-due-total`}>{figures.grades[g]}</strong>
        </span>
      ))}
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}{s} <strong data-testid={`consolidated-status-${s}-count`}>{figures.statuses[s]}</strong>
        </span>
      ))}
    </p>
  );
}

/** Consolidated figures over the sheet and all its descendants (its children — the sheets naming it as their
 *  parent — theirs, and so on), as the store holds them now (while this screen shows the sheet as of a date: every
 *  sheet of the tree as it stood at the end of that day, with that date as its today): the people (those whose names or
 *  aliases match, as names are compared, counted once), the due-total and overdue-total over every person of the tree
 *  (each as their sheet shows it), trimmed once over the whole tree (see trimmedSum), per grade its people's due-totals and per status its claims
 *  counted. A sheet with no children shows its own. */
function Consolidated({ sheetId }: { sheetId: string; user: string }) {
  const [asOf] = useAsOf();
  const descendants = useNow<string[]>(sheetId, 'descendants').data ?? [];
  return <Accumulate sheets={[sheetId, ...descendants]} at={0} sum={NONE}
    asOf={asOf ?? ''} />;
}

export const contribution = SheetBody.fill({ order: -1, Component: Consolidated });
    </section>
  );
}

/** The steward's dashboard: over the sheet and all its descendants (its children — the sheets naming it as their
 *  parent — theirs, and so on), as the store holds them now, how many claims are PENDING, how many REVIEW, and how
 *  many overdue claims count (as each sheet's overdue rollup counts them). Anyone not acting as a steward sees the
 *  cells empty, and so does everyone while the screen shows the sheet as of a date. */
function Dashboard({ sheetId, user }: { sheetId: string; user: string }) {
  const [asOf] = useAsOf();
  const steward = useActingRole(sheetId, user) === 'steward' && !asOf;
  const descendants = useNow<string[]>(sheetId, 'descendants').data ?? [];
  return <Accumulate sheets={[sheetId, ...descendants]} at={0} sum={NONE} steward={steward} />;
}

export const contribution = SheetBody.fill({ order: 21, Component: Dashboard });

